/* ============================================================
   Valida o payload do Send Email Hook e extrai o codigo.

   O Supabase manda:
     body.user.email                    -> destinatario
     body.email_data.token              -> os 6 digitos
     body.email_data.email_action_type  -> 'magiclink' no login por OTP

   IMPORTANTE: este no NUNCA lanca excecao.

   Quando um no estoura com responseMode = responseNode, o
   workflow morre antes de chegar no no de resposta e o n8n
   devolve 200 com corpo vazio. O Supabase leria isso como
   'e-mail entregue' e o avaliador esperaria por um codigo que
   nunca foi enviado. Quem decide o status HTTP e o no IF.

   ORDEM DOS NOS: o Supabase derruba o hook em 5 segundos. Por
   isso o no de resposta vem ANTES do envio pelo Gmail — chamar
   a API do Google primeiro estourava o limite e o login falhava
   com 'Failed to reach hook'. No n8n o workflow continua depois
   do Respond to Webhook, entao o e-mail sai normalmente.
   ============================================================ */

/* Dominios autorizados a receber codigo.

   Este e o unico freio contra alguem que descubra a URL deste
   webhook e passe a usa-lo para disparar e-mail em nome do seu
   dominio. Liste os dominios dos avaliadores (empresas, escolas,
   universidades parceiras).

   Array vazio = aceita qualquer dominio. So faca isso se nao
   houver como enumerar os dominios antes do evento. */
const DOMINIOS_PERMITIDOS = [
  'alfacem.com.br'
];

const corpo  = $input.first().json.body || {};
const email  = (corpo.user && corpo.user.email || '').toLowerCase().trim();
const codigo = corpo.email_data && corpo.email_data.token;
const tipo   = corpo.email_data && corpo.email_data.email_action_type;

/* Nas recusas o codigo nao vai adiante de proposito: assim ele
   nao fica gravado no historico de execucao do n8n. */
if (!email || !codigo) {
  return [{ json: { ok: false, motivo: 'payload_invalido', email, tipo } }];
}

if (DOMINIOS_PERMITIDOS.length) {
  const dominio = email.split('@')[1] || '';
  if (!DOMINIOS_PERMITIDOS.includes(dominio)) {
    return [{ json: { ok: false, motivo: 'dominio_nao_permitido', email, tipo } }];
  }
}

return [{ json: { ok: true, email, codigo, tipo } }];
